[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $commandName = $Command.ToLowerInvariant()
    $configAction = $null
    $configOperands = @()
    $argumentOptions = $CliArguments
    if ($commandName -eq 'config') {
        if ($CliArguments.Count -eq 0 -or $CliArguments[0].StartsWith('--')) {
            throw 'Missing config action: set, get, or list.'
        }
        $configAction = $CliArguments[0].ToLowerInvariant()
        $optionStart = 1
        while ($optionStart -lt $CliArguments.Count -and -not $CliArguments[$optionStart].StartsWith('--')) {
            $configOperands += $CliArguments[$optionStart]
            $optionStart++
        }
        $argumentOptions = @($CliArguments | Select-Object -Skip $optionStart)
    }

    $options = ConvertFrom-TaskForgeArguments -Arguments $argumentOptions
    $repoRoot = Split-Path -Parent $PSScriptRoot
    $configFile = if ($options.Contains('config-file')) {
        [System.IO.Path]::GetFullPath((Get-RequiredOption -Options $options -Name 'config-file'))
    }
    else {
        Join-Path $repoRoot 'data/config.json'
    }
    $config = Read-TaskForgeConfig -Path $configFile
    $dataFileSetting = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    else {
        [string]$config.dataFile
    }
    $dataFile = Resolve-TaskForgePath -Path $dataFileSetting -ConfigFile $configFile
    $asJson = if ($options.Contains('json')) {
        ConvertTo-TaskForgeBoolean -Value $options['json'] -Name '--json'
    }
    else {
        [bool]$config.defaultJson
    }

    switch ($commandName) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json', 'config-file')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'json', 'config-file')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'config' {
            Assert-KnownOptions -Options $options -Allowed @('config-file', 'json')
            switch ($configAction) {
                'set' {
                    if ($configOperands.Count -ne 2) {
                        throw 'Usage: config set KEY VALUE [--config-file PATH] [--json]'
                    }
                    $key = $configOperands[0]
                    if ($key -notin @('dataFile', 'defaultJson')) {
                        throw "Unknown configuration key: $key"
                    }
                    $value = if ($key -eq 'defaultJson') {
                        ConvertTo-TaskForgeBoolean -Value $configOperands[1] -Name 'defaultJson'
                    }
                    else {
                        if ([string]::IsNullOrWhiteSpace($configOperands[1])) {
                            throw 'Configuration key dataFile must be a non-empty path.'
                        }
                        $configOperands[1]
                    }
                    $config[$key] = $value
                    Write-TaskForgeConfig -Path $configFile -Config $config
                    $result = [pscustomobject]@{ key = $key; value = $value }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $result -AsJson $true
                    }
                    else {
                        $displayValue = if ($value -is [bool]) { $value.ToString().ToLowerInvariant() } else { $value }
                        "$key=$displayValue"
                    }
                }
                'get' {
                    if ($configOperands.Count -ne 1) {
                        throw 'Usage: config get KEY [--config-file PATH] [--json]'
                    }
                    $key = $configOperands[0]
                    if ($key -notin @('dataFile', 'defaultJson')) {
                        throw "Unknown configuration key: $key"
                    }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $config[$key] -AsJson $true
                    }
                    else {
                        if ($config[$key] -is [bool]) {
                            $config[$key].ToString().ToLowerInvariant()
                        }
                        else {
                            [string]$config[$key]
                        }
                    }
                }
                'list' {
                    if ($configOperands.Count -ne 0) {
                        throw 'Usage: config list [--config-file PATH] [--json]'
                    }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]$config) -AsJson $true
                    }
                    else {
                        Get-Content -LiteralPath (Join-Path $repoRoot 'assets/config.txt')
                        "dataFile=$($config.dataFile)"
                        "defaultJson=$($config.defaultJson.ToString().ToLowerInvariant())"
                    }
                }
                default {
                    throw "Unknown config action: $configAction"
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @('config-file')
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json [BOOL]]
  list [--data-file PATH] [--json [BOOL]]
  complete --id ID [--data-file PATH] [--json [BOOL]]
  remove --id ID [--data-file PATH] [--json [BOOL]]
  config set KEY VALUE [--json [BOOL]]
  config get KEY [--json [BOOL]]
  config list [--json [BOOL]]
  All commands accept --config-file PATH.
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
